/* Ghi chú học từ – IELTS General Training: đời sống, công việc & cụm từ viết thư (tự biên soạn) – Lexkite, CC BY-SA 4.0 */
(function (g) { const N = g.WORD_NOTES = g.WORD_NOTES || {}; Object.assign(N, {
  // Thuê nhà, nhà ở
  "tenancy agreement": { m: "tenant (người thuê) → tenancy (việc thuê) + agreement (thỏa thuận) → giấy thỏa thuận thuê nhà.", e: "Sai: tenantcy / tenancy contract agreement → Đúng: tenancy agreement. Trọng âm TEN-an-cy.", u: "Reading GT Section 1 (quảng cáo/thông báo nhà cho thuê); thư cho chủ nhà: Under the tenancy agreement, repairs are your responsibility.", f: "tenant (n), tenancy (n), landlord (n), lease (n/v), rental agreement (n, Anh-Mỹ)" },
  "letting agent": { m: "let (Anh-Anh: cho thuê nhà) + agent (đại lý) → bên trung gian cho thuê nhà.", e: "Nhầm 'let' = để/cho phép. Trong nhà đất Anh: let a flat = cho thuê căn hộ. Anh-Mỹ dùng rental agent.", u: "Thư trang trọng gửi bên quản lý nhà: I have contacted the letting agent twice about the leak.", f: "let (v), letting (n), to let (biển cho thuê), estate agent (n, môi giới mua bán)" },
  "fixed-term": { m: "fixed (cố định) + term (kỳ hạn) → có thời hạn định sẵn, ví dụ hợp đồng 12 tháng.", e: "Khi đứng trước danh từ phải có gạch nối: a fixed-term contract. Sau động từ: the contract is for a fixed term.", u: "Reading GT Section 2 (hợp đồng lao động/thuê nhà): a six-month fixed-term tenancy; a fixed-term post.", f: "fixed term (n), fixed-term (adj), permanent (adj, trái nghĩa), rolling contract (n)" },
  "rent arrears": { m: "arrears = khoản 'tụt lại phía sau' (gốc Pháp cổ arere = phía sau) → tiền thuê còn nợ chưa trả.", e: "arrears luôn số nhiều. Sai: a rent arrear → Đúng: rent arrears; be in arrears (đang nợ quá hạn).", u: "Reading GT (nội quy thuê nhà); thư giải thích: I apologise for the rent arrears and will pay in full by Friday.", f: "arrears (n, pl), be in arrears (phr), overdue (adj), outstanding balance (n)" },
  "notice period": { m: "notice (báo trước) + period (khoảng thời gian) → số ngày/tuần phải báo trước khi nghỉ việc hay trả nhà.", e: "Sai: notice time / announcement period → Đúng: notice period. Đọc /ˈnəʊtɪs/, không đọc 'nô-tai'.", u: "Reading GT Section 2 (hợp đồng): The notice period is one month. Thư xin nghỉ việc nhắc đến notice period.", f: "notice (n/v), give notice (phr), serve your notice (phr), noticeable (adj, khác nghĩa)" },
  "give notice": { m: "give (đưa) + notice (lời báo trước) → chính thức báo sẽ nghỉ việc/chuyển đi.", e: "Sai: give a notice to leave / notice the landlord → Đúng: give (one month's) notice; give notice to the landlord.", u: "Thư cho chủ nhà/sếp (Task 1): I am writing to give notice that I will be leaving the flat on 30 June.", f: "notice (n), notify (v), notification (n), hand in your notice (phr, nghỉ việc)" },
  "unfurnished": { m: "un- (không) + furnished (có đồ đạc) → nhà trống, chưa có nội thất.", e: "Sai: unfurniture flat / no furnished → Đúng: an unfurnished flat. furniture là danh từ không đếm được.", u: "Reading GT Section 1 (quảng cáo nhà): two-bedroom flat, unfurnished, available now.", f: "furnish (v), furnished (adj), part-furnished (adj), furniture (n, không đếm được)" },
  "sublet": { m: "sub- (bên dưới, thứ cấp) + let (cho thuê) → cho người khác thuê lại phần mình đang thuê.", e: "Quá khứ vẫn là sublet (không thêm -ed). Sai: subletted → Đúng: sublet. Trọng âm sub-LET (động từ).", u: "Reading GT (nội quy thuê nhà): Tenants may not sublet any part of the property without written consent.", f: "sublet (v/n), subletting (n), subtenant (n), let (v)" },
  "wear and tear": { m: "wear (mòn do dùng) + tear (rách) → hao mòn tự nhiên khi sử dụng bình thường.", e: "tear ở đây đọc /teə/ (xé rách), không đọc /tɪə/ (nước mắt). Thường đi với 'fair' hoặc 'normal'.", u: "Reading GT (hợp đồng thuê, bảo hành): The deposit will not cover fair wear and tear.", f: "wear (v/n), tear (v/n), worn (adj), worn out (adj), damage (n)" },
  "council tax": { m: "council (hội đồng địa phương) + tax (thuế) → thuế nhà đất nộp cho chính quyền địa phương ở Anh.", e: "Sai: council's tax / pay tax for council → Đúng: pay council tax. Không nhầm với income tax (thuế thu nhập).", u: "Reading GT Section 1 (thông tin cho người mới đến): Rent does not include council tax or utility bills.", f: "council (n), councillor (n), local authority (n), tax (n/v), taxpayer (n)" },
  "communal": { m: "Cùng gốc với common/community → thứ thuộc về cả cộng đồng, dùng chung.", e: "Trọng âm Anh-Anh: COM-mu-nal /ˈkɒmjənl/. Sai: communal room for my own → communal = dùng chung, không riêng.", u: "Reading GT (nội quy chung cư/ký túc xá): Please keep the communal kitchen tidy.", f: "communal (adj), community (n), common (adj), shared (adj)" },
  "meter reading": { m: "meter (đồng hồ đo điện/nước/gas) + reading (chỉ số đọc được) → chỉ số công tơ.", e: "meter (đồng hồ đo) khác metre (mét, Anh-Anh). Sai: take a meter read → Đúng: take/submit a meter reading.", u: "Thư cho công ty điện nước: The bill is based on an estimated reading, not my actual meter reading.", f: "meter (n), read (v), reading (n), estimated bill (n), smart meter (n)" },
  "direct debit": { m: "direct (trực tiếp) + debit (ghi nợ, trừ tiền) → ngân hàng tự trừ tiền định kỳ cho bên thu.", e: "Khác standing order: direct debit do bên thu kéo tiền, số tiền có thể thay đổi. Sai: pay with direct debit card.", u: "Reading GT Section 1 (hóa đơn, phòng gym): Payment is by monthly direct debit.", f: "debit (n/v), debit card (n), standing order (n), set up a direct debit (phr)" },
  "standing order": { m: "standing (đứng yên, cố định) + order (lệnh) → lệnh chuyển một khoản cố định đều đặn.", e: "Không phải 'đặt hàng đứng'. Khác direct debit: standing order do chính bạn đặt, số tiền cố định.", u: "Reading GT (thanh toán tiền thuê): Rent must be paid by standing order on the first of each month.", f: "standing (adj), order (n), direct debit (n), bank transfer (n)" },
  "energy supplier": { m: "energy (năng lượng) + supplier (bên cung cấp) → công ty cung cấp điện/gas cho nhà.", e: "Sai: energy provider company of electric → Đúng: energy supplier. Từ supply (v) → supplier (n), đọc /səˈplaɪə/.", u: "Reading GT Section 1 (chuyển nhà): Contact your energy supplier to give a meter reading when you move in.", f: "supply (v/n), supplier (n), utility company (n), switch supplier (phr)" },
  "blocked": { m: "block (khối, chặn) → blocked: bị chặn lại, nước không chảy qua được.", e: "Đọc /blɒkt/, một âm tiết, không đọc 'bờ-lốc-kéd'. Sai: the sink is block → Đúng: the sink is blocked.", u: "Thư khiếu nại chủ nhà (Task 1): The kitchen drain has been blocked for over a week.", f: "block (v/n), blockage (n), unblock (v), clogged (adj)" },
  "pest control": { m: "pest (sinh vật gây hại: chuột, gián) + control (kiểm soát) → dịch vụ diệt côn trùng, chuột.", e: "Sai: insect control service of mouse → Đúng: pest control. pest khác past/paste.", u: "Thư gửi ban quản lý: I would be grateful if you could arrange pest control as soon as possible.", f: "pest (n), pesticide (n), infestation (n), exterminator (n)" },
  "bin collection": { m: "bin (thùng rác) + collection (việc thu gom) → lịch thu gom rác.", e: "Anh-Anh: bin, rubbish; Anh-Mỹ: trash can, garbage. Sai: rubbish taking day → Đúng: bin collection day.", u: "Reading GT Section 1 (thông báo khu phố): Bin collection will be on Tuesday this week due to the bank holiday.", f: "bin (n), collect (v), collection (n), rubbish (n), refuse collection (n, trang trọng)" },
  "recycling bin": { m: "re- (lại) + cycle (vòng) → recycling (tái chế) + bin (thùng) → thùng rác tái chế.", e: "Sai: recycle bin (thường chỉ thùng rác máy tính) → Đúng ở đời thực: recycling bin. Đọc /riːˈsaɪklɪŋ/.", u: "Reading GT (hướng dẫn phân loại rác): Glass bottles go in the recycling bin, not general waste.", f: "recycle (v), recycling (n), recyclable (adj), general waste (n)" },
  "smoke alarm": { m: "smoke (khói) + alarm (chuông báo) → thiết bị kêu khi phát hiện khói.", e: "Sai: smoking alarm (nghe như chuông báo người hút thuốc) → Đúng: smoke alarm / smoke detector.", u: "Reading GT (an toàn nhà ở): Test your smoke alarm once a month. Thư báo hỏng: The smoke alarm keeps beeping.", f: "smoke (n/v), alarm (n), fire alarm (n), smoke detector (n)" },
  // Mua sắm, đổi trả
  "proof of purchase": { m: "proof (bằng chứng) + purchase (việc mua) → hóa đơn, biên lai chứng minh đã mua.", e: "Sai: proof of buying / prove of purchase → Đúng: proof of purchase. prove (v), proof (n).", u: "Reading GT Section 1 (chính sách đổi trả): Refunds are given only with proof of purchase.", f: "proof (n), prove (v), purchase (n/v), receipt (n)" },
  "store credit": { m: "store (cửa hàng) + credit (tiền ghi có) → phiếu/tiền chỉ dùng mua tại chính cửa hàng đó.", e: "Không phải 'thẻ tín dụng cửa hàng'. Khác refund (trả lại tiền). Sai: get store credit money back.", u: "Reading GT (chính sách đổi trả): Items without a receipt can be exchanged for store credit only.", f: "credit (n), credit note (n, Anh-Anh), voucher (n), refund (n/v)" },
  "statutory rights": { m: "statute (đạo luật) → statutory (do luật quy định) + rights → quyền lợi theo luật của người tiêu dùng.", e: "Đọc /ˈstætʃətri/, không đọc 'sta-tu-to-ri'. Sai: statue rights (statue = bức tượng).", u: "Reading GT (điều khoản cửa hàng): This does not affect your statutory rights.", f: "statute (n), statutory (adj), consumer rights (n), legal right (n)" },
  "goodwill gesture": { m: "goodwill (thiện chí) + gesture (cử chỉ) → khoản bù đắp tự nguyện để giữ khách.", e: "Thường nói 'as a goodwill gesture' hoặc 'a gesture of goodwill'. Sai: a good will gesture of apology.", u: "Thư khiếu nại có thể đề xuất: I would accept a voucher as a goodwill gesture.", f: "goodwill (n), gesture (n), compensation (n), apology (n)" },
  "customer services": { m: "customer (khách) + services (bộ phận dịch vụ) → bộ phận chăm sóc khách hàng.", e: "Anh-Anh hay dùng customer services (số nhiều) cho phòng ban. Sai: custom service (custom = phong tục/hải quan).", u: "Thư khiếu nại: I contacted customer services on 3 May but received no reply.", f: "customer (n), service (n), customer service (n, chất lượng phục vụ), helpline (n)" },
  "delivery charge": { m: "delivery (giao hàng) + charge (phí) → phí giao hàng.", e: "Sai: delivery fee money / ship charge → Đúng: delivery charge, free delivery. charge cũng là động từ: charge for delivery.", u: "Reading GT (quảng cáo cửa hàng): No delivery charge on orders over £50.", f: "deliver (v), delivery (n), charge (n/v), postage (n)" },
  "non-refundable": { m: "non- (không) + refund (hoàn tiền) + -able (có thể) → không được hoàn lại tiền.", e: "Có gạch nối: non-refundable. Sai: unrefundable / not refund deposit → Đúng: a non-refundable deposit.", u: "Reading GT (vé, đặt cọc khóa học): A non-refundable deposit of £30 is required.", f: "refund (n/v), refundable (adj), non-refundable (adj), deposit (n)" },
  "cooling-off period": { m: "cool off (nguội đi, bình tĩnh lại) → khoảng thời gian luật cho phép đổi ý, hủy hợp đồng.", e: "Không phải 'thời gian làm mát'. Có gạch nối: cooling-off period. Thường 14 ngày khi mua online ở Anh.", u: "Reading GT (điều khoản hợp đồng): You may cancel within the 14-day cooling-off period.", f: "cool off (phr v), cancel (v), cancellation (n), terms and conditions (n)" },
  "small print": { m: "small (nhỏ) + print (chữ in) → phần chữ nhỏ chứa điều khoản dễ bị bỏ qua.", e: "Luôn có 'the': read the small print. Anh-Mỹ: fine print. Không dùng số nhiều 'small prints'.", u: "Reading GT (quảng cáo, hợp đồng): Always check the small print before signing.", f: "print (n/v), fine print (n, Anh-Mỹ), terms and conditions (n), clause (n)" },
  // Thể thao, giải trí, dịch vụ
  "leisure centre": { m: "leisure (thời gian rảnh) + centre (trung tâm) → trung tâm thể thao công cộng có hồ bơi, phòng gym.", e: "Đọc Anh-Anh /ˈleʒə/ (le-giờ). Anh-Anh: centre; Anh-Mỹ: center. Sai: relax centre.", u: "Reading GT Section 1 (tờ rơi trung tâm thể thao): The leisure centre is open seven days a week.", f: "leisure (n), leisurely (adj), sports centre (n), gym (n)" },
  "peak times": { m: "peak (đỉnh) + times (khung giờ) → giờ cao điểm, đông người nhất.", e: "Sai: peek times (peek = nhìn trộm) → Đúng: peak times. Trái nghĩa: off-peak.", u: "Reading GT (bảng giá gym, tàu xe): Off-peak membership excludes peak times (5–8 pm).", f: "peak (n/adj), off-peak (adj), rush hour (n), busy period (n)" },
  "lane swimming": { m: "lane (làn) + swimming (bơi) → giờ bơi theo làn riêng, thường chia nhanh/chậm.", e: "Sai: swimming lane time / swim by lane → Đúng: lane swimming sessions. lane khác line (dòng kẻ).", u: "Reading GT (lịch hồ bơi): Lane swimming: Mon–Fri 7–9 am, fast, medium and slow lanes.", f: "lane (n), swimming (n), public swim (n), swimming pool (n)" },
  "drop-in session": { m: "drop in (ghé qua, không hẹn) → buổi sinh hoạt cứ đến là tham gia, không cần đăng ký.", e: "Có gạch nối khi làm tính từ: a drop-in session. Sai: drop session / drop-in a session.", u: "Reading GT (lịch lớp, phòng khám): Drop-in sessions run every Wednesday – no booking required.", f: "drop in (phr v), drop-in (adj/n), walk-in (adj), appointment (n)" },
  "joining fee": { m: "join (tham gia) + fee (phí) → phí đóng một lần khi mới đăng ký hội viên.", e: "Sai: join fee / fee to join in → Đúng: joining fee. Đừng nhầm với monthly fee (phí hằng tháng).", u: "Reading GT (bảng giá phòng gym): No joining fee if you sign up this month.", f: "join (v), joining fee (n), membership fee (n), subscription (n)" },
  "evening class": { m: "evening (buổi tối) + class (lớp) → lớp học buổi tối cho người đi làm.", e: "Sai: night class at the evening / evening's class → Đúng: take/attend an evening class in Spanish.", u: "Reading GT (tờ rơi trung tâm giáo dục người lớn); thư cho bạn: I've started an evening class in pottery.", f: "evening (n), class (n), adult education (n), course (n)" },
  "supervised": { m: "super- (trên) + vise (nhìn) → có người đứng trên nhìn, trông chừng.", e: "Đọc /ˈsuːpəvaɪzd/, đuôi -ed đọc /d/. Sai: supervisor activity → Đúng: supervised activity.", u: "Reading GT (nội quy trẻ em): Children must be supervised at all times in the pool area.", f: "supervise (v), supervisor (n), supervision (n), unsupervised (adj)" },
  "accompanied by an adult": { m: "accompany (đi cùng) ở bị động + by an adult → phải có người lớn đi kèm.", e: "Sai: accompanied with an adult / accompany by parents → Đúng: accompanied by an adult. Chính tả: hai chữ c, một chữ m.", u: "Reading GT (nội quy): Children under 8 must be accompanied by an adult.", f: "accompany (v), companion (n), unaccompanied (adj), supervised (adj)" },
  "opening hours": { m: "opening (mở cửa) + hours (giờ) → giờ mở cửa của cửa hàng, dịch vụ.", e: "Sai: open hours time / opening time hours → Đúng: opening hours (số nhiều). Có thể dùng opening times.", u: "Reading GT Section 1 (thông báo): Opening hours will change over the holiday period.", f: "open (v/adj), opening (n), closing time (n), business hours (n)" },
  "refurbishment": { m: "re- (lại) + furbish (đánh bóng, làm mới) + -ment → việc tân trang, sửa sang lại.", e: "Đọc /ˌriːˈfɜːbɪʃmənt/. Sai: closed for refurbish → Đúng: closed for refurbishment.", u: "Reading GT (thông báo): The pool will be closed for refurbishment from 1 to 14 March.", f: "refurbish (v), refurbished (adj), renovation (n), renovate (v)" },
  "gp": { m: "Viết tắt general practitioner: bác sĩ đa khoa (general) hành nghề (practise) ở khu dân cư.", e: "Đọc từng chữ /ˌdʒiː ˈpiː/. Sai: go to GP / register GP → Đúng: see your GP, register with a GP.", u: "Reading GT Section 1 (dịch vụ y tế cho người mới đến): Register with a local GP as soon as possible.", f: "general practitioner (n), GP surgery (n), doctor's (n), appointment (n)" },
  "out-of-hours": { m: "out of hours = ngoài giờ làm việc → dịch vụ phục vụ buổi tối, cuối tuần, ngày lễ.", e: "Có gạch nối khi đứng trước danh từ: an out-of-hours service. Sai: out-hours / over hours.", u: "Reading GT (thông tin phòng khám): For urgent care at night, call the out-of-hours service.", f: "out of hours (adv), after-hours (adj), opening hours (n), emergency (n)" },
  "proof of address": { m: "proof (bằng chứng) + of address (về địa chỉ) → giấy tờ chứng minh nơi ở như hóa đơn điện.", e: "Sai: address proof paper / prove of address → Đúng: proof of address. Thường kèm photo ID.", u: "Reading GT (mở tài khoản, đăng ký thẻ thư viện): Bring photo ID and proof of address.", f: "proof (n), prove (v), address (n), utility bill (n)" },
  "current account": { m: "current (hiện hành, dùng hằng ngày) + account → tài khoản thanh toán để chi tiêu thường ngày.", e: "Không phải 'tài khoản hiện tại'. Anh-Mỹ: checking account. Khác savings account (tài khoản tiết kiệm).", u: "Reading GT (tờ rơi ngân hàng): Open a current account online in ten minutes.", f: "account (n), savings account (n), checking account (n, Anh-Mỹ), bank statement (n)" },
  "overdraft": { m: "over (vượt) + draft (rút tiền) → được rút vượt số dư, tức là nợ ngân hàng.", e: "Sai: I am overdraft → Đúng: I am overdrawn / I have an overdraft. overdraft là danh từ.", u: "Reading GT (điều khoản ngân hàng): An arranged overdraft of up to £500 is available.", f: "overdraft (n), overdraw (v), overdrawn (adj), arranged overdraft (n)" },
  "season ticket": { m: "season (một mùa/thời kỳ) + ticket → vé dùng nhiều lần trong một khoảng thời gian, như vé tháng/năm.", e: "Không chỉ dùng cho bốn mùa. Sai: monthly season / season card → Đúng: an annual season ticket.", u: "Reading GT (giao thông, sân vận động): A season ticket is cheaper than buying daily tickets.", f: "season (n), ticket (n), travelcard (n), pass (n)" },
  "bus pass": { m: "bus + pass (thẻ ra vào) → thẻ đi xe buýt trong một thời gian hoặc giảm giá.", e: "Sai: bus card ticket / bus passport → Đúng: a bus pass. Người cao tuổi ở Anh có free bus pass.", u: "Reading GT (thông tin cho sinh viên, người cao tuổi): Apply for a student bus pass online.", f: "pass (n/v), season ticket (n), fare (n), concession (n)" },
  "lost property": { m: "lost (bị mất) + property (đồ đạc) → đồ thất lạc; cũng là phòng giữ đồ thất lạc.", e: "Anh-Mỹ: lost and found. property ở đây không đếm được. Sai: a lost properties office.", u: "Thư Task 1 hỏi về đồ để quên: I left my bag on the train and wonder if it has been handed in to lost property.", f: "lose (v), lost (adj), property (n), lost and found (n, Anh-Mỹ)" },
  // Việc làm
  "job advert": { m: "advert = advertisement viết gọn (Anh-Anh) → tin tuyển dụng.", e: "Đọc /ˈædvɜːt/, trọng âm đầu. Anh-Mỹ: job ad. Sai: job advertise (advertise là động từ).", u: "Reading GT Section 2 (tin tuyển dụng); thư xin việc: I saw your job advert in the local paper.", f: "advertise (v), advertisement (n), advert/ad (n), vacancy (n)" },
  "part-time": { m: "part (một phần) + time → làm một phần thời gian, ít giờ hơn toàn thời gian.", e: "Gạch nối khi làm tính từ/trạng từ: a part-time job, work part-time. Sai: a part time's job.", u: "Reading GT Section 2 (tin tuyển dụng): Part-time staff required, 20 hours per week.", f: "full-time (adj/adv), part-timer (n), shift (n), hours (n)" },
  "flexible hours": { m: "flexible (linh hoạt, uốn được) + hours → giờ làm có thể tự điều chỉnh.", e: "Đọc /ˈfleksəbl/. Sai: flexibility hours / flexible time working → Đúng: flexible hours, flexitime.", u: "Reading GT (phúc lợi công việc): We offer flexible hours and remote working.", f: "flexible (adj), flexibility (n), flexitime (n), working hours (n)" },
  "pro rata": { m: "Tiếng Latin 'theo tỷ lệ' → lương tính theo tỷ lệ số giờ thực làm.", e: "Đọc /ˌprəʊ ˈrɑːtə/. Đừng hiểu £30,000 pro rata là lương thực nhận; người làm bán thời gian nhận ít hơn theo tỷ lệ.", u: "Reading GT (tin tuyển dụng): Salary £24,000 pro rata (3 days per week).", f: "proportion (n), proportionate (adj), per annum (adv), part-time (adj)" },
  "per annum": { m: "Tiếng Latin: per (mỗi) + annum (năm) → mỗi năm. Hay viết tắt p.a.", e: "Đọc /pər ˈænəm/. Sai: per annual → Đúng: per annum, a year. Không dùng trong thư thân mật.", u: "Reading GT (tin tuyển dụng, lãi suất): Salary: £28,000 per annum.", f: "annual (adj), annually (adv), p.a. (abbr), per year (phr)" },
  "starting salary": { m: "starting (khởi điểm) + salary (lương tháng/năm) → mức lương lúc mới vào làm.", e: "Sai: beginning salary / start salary → Đúng: starting salary. salary khác wage (lương theo giờ/tuần).", u: "Reading GT (tin tuyển dụng): Starting salary £22,000, rising after probation.", f: "salary (n), salaried (adj), wage (n), pay rise (n)" },
  "relevant experience": { m: "relevant (liên quan, phù hợp) + experience → kinh nghiệm phù hợp với vị trí.", e: "Sai: relative experience (relative = họ hàng/tương đối) → Đúng: relevant experience. experience ở đây không đếm được.", u: "Thư xin việc: I have three years of relevant experience in customer service.", f: "relevant (adj), relevance (n), irrelevant (adj), experienced (adj)" },
  "closing date": { m: "closing (đóng lại) + date (ngày) → hạn chót nộp hồ sơ.", e: "Sai: close date / end date for apply → Đúng: The closing date for applications is 15 May.", u: "Reading GT Section 2 (tin tuyển dụng): Closing date: 31 March. Late applications will not be accepted.", f: "close (v), closing (adj), deadline (n), application (n)" },
  "contract of employment": { m: "contract (hợp đồng) + of employment (việc làm) → hợp đồng lao động.", e: "Sai: employment's contract / labour contract (ít dùng ở Anh) → Đúng: contract of employment / employment contract.", u: "Reading GT Section 2 (quy định nhân sự): Your contract of employment sets out your hours and pay.", f: "contract (n), employ (v), employment (n), employer/employee (n)" },
  "apprenticeship": { m: "apprentice (người học nghề) + -ship (trạng thái) → chương trình vừa học vừa làm.", e: "Đọc /əˈprentɪsʃɪp/. Sai: an apprentice program for learn → Đúng: do/start an apprenticeship.", u: "Reading GT (đào tạo nghề): Apprenticeships combine paid work with college study.", f: "apprentice (n), apprenticeship (n), trainee (n), vocational training (n)" },
  "self-employed": { m: "self (tự mình) + employed (có việc làm) → tự làm chủ, không làm thuê cho ai.", e: "Có gạch nối. Sai: I am self-employ / self-employment person → Đúng: I am self-employed.", u: "Reading GT (thuế, bảo hiểm); thư cho bạn: I've been self-employed since last year.", f: "self-employed (adj), self-employment (n), freelance (adj/n), employee (n)" },
  "annual leave": { m: "annual (hằng năm) + leave (nghỉ phép) → số ngày nghỉ phép có lương mỗi năm.", e: "leave ở đây là danh từ không đếm được. Sai: take an annual leave / annual leaves → Đúng: take annual leave.", u: "Reading GT Section 2 (chính sách nhân sự): Staff are entitled to 25 days' annual leave.", f: "leave (n), sick leave (n), maternity leave (n), holiday entitlement (n)" },
  "entitlement": { m: "entitle (cho quyền) + -ment → quyền được hưởng; mức được hưởng.", e: "Sai: I am entitlement to → Đúng: I am entitled to / my entitlement is. Đọc /ɪnˈtaɪtlmənt/.", u: "Reading GT Section 2 (nhân sự): Holiday entitlement rises with length of service.", f: "entitle (v), entitled (adj), entitlement (n), be entitled to (phr)" },
  "line manager": { m: "line (tuyến báo cáo) + manager → người quản lý trực tiếp của bạn.", e: "Không phải 'quản lý dây chuyền'. Sai: my direct line's manager → Đúng: report to your line manager.", u: "Reading GT Section 2 (quy trình nội bộ): Request annual leave from your line manager.", f: "manager (n), supervisor (n), report to (phr v), management (n)" },
  "payslip": { m: "pay (lương) + slip (mảnh giấy) → phiếu lương ghi các khoản lương và khấu trừ.", e: "Viết liền payslip (Anh-Anh). Anh-Mỹ: pay stub. Sai: salary paper / pay sheet.", u: "Reading GT Section 2 (lương thưởng): Check your payslip for tax and pension deductions.", f: "pay (n/v), slip (n), deduction (n), pay stub (n, Anh-Mỹ)" },
  "clock in": { m: "Ngày xưa nhân viên bấm thẻ vào đồng hồ chấm công (clock) → bắt đầu ca làm.", e: "Trái nghĩa: clock out/off. Sai: clock on in work / check clock → Đúng: clock in at 8 am.", u: "Reading GT Section 2 (nội quy ca làm): All staff must clock in on arrival.", f: "clock in/on (phr v), clock out/off (phr v), timesheet (n), shift (n)" },
  "call in sick": { m: "call in (gọi điện báo về cơ quan) + sick → gọi báo nghỉ ốm.", e: "Sai: call sick in / call in sickness → Đúng: call in sick. Chủ ngữ là người lao động.", u: "Reading GT Section 2 (nội quy vắng mặt): If you call in sick, phone your manager before 9 am.", f: "sick (adj), sick leave (n), sick note (n), absence (n)" },
  "sick note": { m: "sick (ốm) + note (giấy ghi) → giấy chứng nhận ốm của bác sĩ.", e: "Sai: sickness paper / ill note → Đúng: sick note (thân mật), fit note/medical certificate (trang trọng).", u: "Reading GT Section 2 (nhân sự): A sick note is required for absences of more than seven days.", f: "sick (adj), note (n), fit note (n), medical certificate (n)" },
  "rest break": { m: "rest (nghỉ ngơi) + break (giờ giải lao) → thời gian nghỉ trong ca làm.", e: "Sai: break rest / take a rest's break → Đúng: take a rest break, have a 20-minute break.", u: "Reading GT Section 2 (quyền lợi lao động): Workers are entitled to a 20-minute rest break.", f: "rest (n/v), break (n), lunch break (n), tea break (n)" },
  "staff room": { m: "staff (nhân viên) + room → phòng nghỉ, phòng sinh hoạt chung của nhân viên.", e: "staff là danh từ tập hợp: the staff are/is. Sai: staffs room / staff's room → Đúng: staff room.", u: "Reading GT Section 2 (nội quy): Please wash your cups in the staff room.", f: "staff (n), staffing (n), staff canteen (n), break room (n, Anh-Mỹ)" },
  "confidentiality": { m: "confide (tin cậy kể bí mật) → confidential (bí mật) + -ity → tính bảo mật.", e: "Đọc /ˌkɒnfɪˌdenʃiˈæləti/, trọng âm chính ở -AL-. Sai: confidential (adj) dùng thay danh từ.", u: "Reading GT Section 2 (quy định công ty): Staff must maintain confidentiality about customer data.", f: "confide (v), confidential (adj), confidentially (adv), confidentiality agreement (n)" },
  "grievance": { m: "grieve (đau buồn) → grievance: điều khiến mình bất bình, khiếu nại chính thức.", e: "Đọc /ˈɡriːvəns/. Sai: grievence. Ở công sở: raise/file a grievance (khiếu nại chính thức).", u: "Reading GT Section 2 (quy trình khiếu nại): Follow the grievance procedure if you have a complaint.", f: "grieve (v), grief (n), grievance (n), complaint (n)" },
  "disciplinary": { m: "discipline (kỷ luật) + -ary → thuộc về kỷ luật, xử phạt.", e: "Đọc Anh-Anh /ˌdɪsəˈplɪnəri/. Sai: discipline action → Đúng: disciplinary action/hearing.", u: "Reading GT Section 2 (nội quy): Theft will result in disciplinary action.", f: "discipline (n/v), disciplinary (adj), disciplined (adj), misconduct (n)" },
  "health and safety": { m: "health (sức khỏe) + safety (an toàn) → an toàn lao động, cụm cố định ở Anh.", e: "Không đảo thành safety and health. Làm tính từ: health and safety rules/training.", u: "Reading GT Section 2 (hướng dẫn nơi làm việc): All new staff must attend health and safety training.", f: "health (n), healthy (adj), safety (n), safe (adj)" },
  "first aider": { m: "first aid (sơ cứu) + -er → người được đào tạo sơ cứu tại nơi làm việc.", e: "Viết hai chữ: first aider. Sai: first aid man / first-aidder. Hỏi: Who is the first aider on this floor?", u: "Reading GT Section 2 (an toàn): Report all injuries to a trained first aider.", f: "first aid (n), first aid kit (n), first aider (n), paramedic (n)" },
  "accident book": { m: "accident (tai nạn) + book (sổ) → sổ ghi lại mọi tai nạn tại nơi làm việc.", e: "Sai: accident note book / write in accident record → Đúng: record it in the accident book.", u: "Reading GT Section 2 (an toàn lao động): All injuries, however minor, must be recorded in the accident book.", f: "accident (n), accidental (adj), incident report (n), injury (n)" },
  "fire drill": { m: "drill (luyện tập lặp lại như khoan) → buổi diễn tập chữa cháy, thoát hiểm.", e: "Sai: fire practice / fire training run → Đúng: hold/carry out a fire drill.", u: "Reading GT Section 2 (thông báo): A fire drill will take place on Thursday at 10 am.", f: "drill (n/v), fire alarm (n), evacuate (v), evacuation (n)" },
  "assembly point": { m: "assemble (tập hợp) → assembly (sự tập hợp) + point (điểm) → điểm tập kết khi sơ tán.", e: "Sai: gathering place point / meeting point (dùng khi hẹn gặp) → trong an toàn cháy nổ: assembly point.", u: "Reading GT Section 2 (an toàn): Leave by the nearest exit and go to the assembly point in the car park.", f: "assemble (v), assembly (n), evacuate (v), fire exit (n)" },
  "manual handling": { m: "manual (bằng tay) + handling (xử lý, mang vác) → mang vác, nâng hạ đồ bằng sức người.", e: "Không phải 'sổ tay hướng dẫn'. manual handling = nâng/vác vật nặng đúng tư thế.", u: "Reading GT Section 2 (an toàn kho bãi): Complete manual handling training before lifting heavy boxes.", f: "manual (adj/n), manually (adv), handle (v), lifting (n)" },
  "slippery": { m: "slip (trượt) + -ery → trơn, dễ làm trượt ngã.", e: "Gấp đôi p: slippery. Sai: slipery / slippy floor (slippy là thân mật). Biển báo: Caution – slippery floor.", u: "Reading GT Section 2 (biển báo an toàn): The floor may be slippery when wet.", f: "slip (v/n), slippery (adj), slippy (adj, thân mật), wet floor (n)" },
  "hard hat": { m: "hard (cứng) + hat (mũ) → mũ bảo hộ trên công trường.", e: "Sai: hard helmet / safety hard hat → Đúng: wear a hard hat. Hai từ, không gạch nối.", u: "Reading GT Section 2 (an toàn công trường): Hard hats must be worn on site at all times.", f: "hard hat (n), helmet (n), protective clothing (n), PPE (n)" },
  // Mở thư, kết thư
  "dear sir or madam": { m: "Không biết tên người nhận → chào chung cả 'ông' (Sir) và 'bà' (Madam).", e: "Mở bằng Dear Sir or Madam thì kết Yours faithfully. Sai: Dear Sir or Madam + Best wishes, hoặc dùng khi đã biết tên.", u: "Task 1 thư trang trọng gửi công ty/phòng ban không rõ tên: Dear Sir or Madam, I am writing to complain about...", f: "Dear Mr Smith (formal, biết tên), Dear Ms Lee (formal), Yours faithfully (formal)" },
  "to whom it may concern": { m: "Nghĩa đen: gửi người mà việc này liên quan → không biết ai sẽ đọc.", e: "Rất trang trọng, hợp với thư giới thiệu/xác nhận. Task 1 nên ưu tiên Dear Sir or Madam. Không dùng cho thư bạn bè.", u: "Thư giới thiệu, xác nhận chung (formal): To whom it may concern, I am pleased to recommend...", f: "Dear Sir or Madam (formal), Yours faithfully (formal), reference letter (n)" },
  "yours faithfully": { m: "Faithfully đi với 'không biết tên' (Dear Sir or Madam): F – F, không tên.", e: "Sai: dùng Yours faithfully khi đã gọi tên (Dear Mr Brown) → Đúng: Yours sincerely. Không viết Your faithfully.", u: "Kết thư Task 1 trang trọng, không biết tên người nhận: Yours faithfully, (xuống dòng) Nam Nguyen.", f: "Yours sincerely (formal, biết tên), Kind regards (semi-formal), Dear Sir or Madam (formal)" },
  "yours sincerely": { m: "Sincerely đi với thư đã biết tên: S – Surname (họ người nhận).", e: "Sai: Dear Sir or Madam + Yours sincerely, hoặc dùng cho bạn thân. Không viết Yours Sincerely với S hoa ở từ thứ hai.", u: "Kết thư Task 1 trang trọng hoặc bán trang trọng khi biết tên: Dear Mr Taylor, ... Yours sincerely,", f: "Yours faithfully (formal, không tên), Kind regards (semi-formal), sincerely (adv)" },
  "kind regards": { m: "regards = lời hỏi thăm, gửi kính trọng → kết thư lịch sự, ấm áp vừa phải.", e: "Hợp thư bán trang trọng (gửi hàng xóm, đồng nghiệp). Không dùng cho thư trang trọng gửi Dear Sir or Madam, cũng hơi khô với bạn thân.", u: "Task 1 bán trang trọng: Dear Mrs Lee, ... Kind regards, Minh.", f: "Best regards (semi-formal), Regards (neutral), Yours sincerely (formal), Best wishes (informal)" },
  "best wishes": { m: "Chúc những điều tốt nhất → kết thư thân thiện.", e: "Hợp thư thân mật hoặc bán trang trọng. Sai: kết thư khiếu nại công ty bằng Best wishes; dùng Yours faithfully/sincerely.", u: "Task 1 thư cho bạn/người quen: Hope to see you soon. Best wishes, Hoa.", f: "All the best (informal), Kind regards (semi-formal), Take care (informal), wish (v/n)" },
  "all the best": { m: "Chúc mọi điều tốt đẹp nhất → kết thư thân mật, gọn.", e: "Chỉ dùng cho thư thân mật. Sai: All the best sau Dear Sir or Madam. Không viết All the bests.", u: "Task 1 thư cho bạn: Good luck with the new job! All the best, Tuan.", f: "Best wishes (informal), Take care (informal), Cheers (rất thân mật), Kind regards (semi-formal)" },
  "lots of love": { m: "Rất nhiều yêu thương → kết thư cho gia đình, bạn rất thân.", e: "Rất thân mật, chỉ dùng cho người thân, bạn thân. Sai: gửi sếp hoặc chủ nhà. Không viết Lot of loves.", u: "Task 1 thư cho người nhà/bạn thân: Can't wait to see you all. Lots of love, Mai.", f: "Love (informal), Much love (informal), Best wishes (informal), Take care (informal)" },
  "take care": { m: "Hãy giữ gìn → lời chào tạm biệt quan tâm cuối thư bạn bè.", e: "Thân mật. Sai: Take care of yourselves, Yours faithfully (trộn giọng). Không dùng trong thư trang trọng gửi công ty.", u: "Task 1 thư cho bạn, ngay trước tên ký: Take care, and write back soon! Lan", f: "Take care of (phr v), careful (adj), Best wishes (informal), All the best (informal)" },
  // Mở đầu thư thân mật
  "it was great to hear from you": { m: "hear from sb = nhận thư/tin từ ai → câu mở thư hồi âm thân mật.", e: "Sai: hear of you (= nghe nói về) / It was great to hear you → Đúng: hear from you. Không dùng trong thư trang trọng.", u: "Câu đầu thư thân mật Task 1 khi trả lời bạn: It was great to hear from you after so long!", f: "hear from (phr v), Thanks for your letter (informal), Lovely to hear from you (informal)" },
  "thanks for your letter": { m: "Thanks (thân mật) thay cho Thank you → mở đầu thư trả lời bạn bè.", e: "Thân mật. Trong thư trang trọng dùng: Thank you for your letter of 5 May. Sai: Thanks for your letter, Yours faithfully.", u: "Task 1 thư thân mật (hồi âm): Thanks for your letter – it was lovely to hear your news.", f: "Thank you for your letter (formal), Thanks for your email (informal), It was great to hear from you (informal)" },
  "how are you doing?": { m: "Câu hỏi thăm thân mật, giống 'Dạo này cậu thế nào?'.", e: "Chỉ dùng thư bạn bè. Sai: How are you doing? trong thư gửi công ty. Đừng viết How do you do? (lời chào khi gặp lần đầu).", u: "Mở đầu Task 1 thân mật: Hi Tom, How are you doing? I hope work isn't too busy.", f: "How are things? (informal), How have you been? (informal), I hope you're well (neutral)" },
  "i hope this letter finds you well": { m: "Nghĩa đen: mong lá thư đến khi bạn đang khỏe → lời hỏi thăm lịch sự.", e: "Hơi trang trọng/kiểu cách; với bạn thân dùng I hope you're well. Không dùng trong thư khiếu nại. Sai: find you well.", u: "Mở thư bán trang trọng (gửi thầy cô cũ, người quen): Dear Mrs Green, I hope this letter finds you well.", f: "I hope you're well (neutral), I hope all is well (neutral), How are you doing? (informal)" },
  "sorry i haven't written for so long": { m: "Present perfect + for so long → lâu rồi không viết, đến giờ vẫn vậy.", e: "Sai: Sorry I didn't write for so long / since so long → Đúng: haven't written for so long. Chỉ dùng thư thân mật.", u: "Mở thư bạn bè Task 1: Sorry I haven't written for so long – I've been really busy with my new job.", f: "Sorry for the late reply (informal), It's been ages (informal), apologise (v, formal)" },
  "i thought i'd drop you a line": { m: "drop sb a line = gửi ai vài dòng → viết thư ngắn hỏi thăm.", e: "Rất thân mật. Sai: drop a line to you to inform (trộn giọng) / I thought I drop. Không dùng với công ty.", u: "Mở thư thân mật: I thought I'd drop you a line to tell you about my holiday.", f: "drop sb a line (idiom), get in touch (phr), write to (v), I'm writing to let you know (informal)" },
  "guess what!": { m: "Đoán xem nào! → mở màn cho tin bất ngờ, giọng hào hứng.", e: "Chỉ dùng thư thân mật; tuyệt đối không dùng trong thư trang trọng. Sai: Guess what? I am writing to inform you that...", u: "Task 1 thư báo tin vui cho bạn: Guess what! I've finally passed my driving test.", f: "You'll never guess (informal), guess (v/n), I've got some great news (informal)" },
  "i'm writing to let you know": { m: "let sb know = cho ai biết → mục đích thư, giọng thân mật/trung tính.", e: "Dạng viết tắt I'm hợp thư thân mật. Thư trang trọng dùng I am writing to inform you that. Sai: let you to know.", u: "Câu nêu mục đích thư thân mật: I'm writing to let you know that I'm moving to Manchester.", f: "let sb know (phr), I am writing to inform you (formal), Please let me know (neutral)" },
  // Mở đầu thư trang trọng, nêu mục đích
  "i am writing to enquire about": { m: "enquire = hỏi thông tin (Anh-Anh), trang trọng hơn ask → mục đích hỏi thông tin.", e: "Sai: enquire for / enquire the course → Đúng: enquire about + N/V-ing. Đừng viết I'm writing to ask (quá thân mật).", u: "Câu đầu thư Task 1 trang trọng: I am writing to enquire about the evening Spanish course.", f: "enquire/inquire (v), enquiry (n), I would like further information about (formal)" },
  "i am writing to complain about": { m: "complain about = phàn nàn về → câu mở thư khiếu nại rõ mục đích.", e: "Sai: complain for / complain the service → Đúng: complain about. Không viết I'm writing to moan about (quá thân mật).", u: "Câu đầu thư khiếu nại Task 1: I am writing to complain about the poor service I received on 12 May.", f: "complain (v), complaint (n), make a complaint (phr), I wish to express my dissatisfaction (formal)" },
  "i am writing to apply for": { m: "apply for = nộp đơn xin (việc, học bổng) → câu mở đơn ứng tuyển.", e: "Sai: apply to the position / apply the job → Đúng: apply for the position (apply to + công ty).", u: "Thư xin việc Task 1: I am writing to apply for the position of receptionist advertised on your website.", f: "apply (v), application (n), applicant (n), I saw your advertisement in (formal)" },
  "i am writing to inform you that": { m: "inform sb that = thông báo cho ai → mục đích báo tin, trang trọng.", e: "Sai: inform to you / inform you about that + clause → Đúng: inform you that + mệnh đề. Với bạn bè dùng let you know.", u: "Thư trang trọng báo thay đổi: I am writing to inform you that I will be moving out on 30 June.", f: "inform (v), information (n), informative (adj), I'm writing to let you know (informal)" },
  "i am writing in connection with": { m: "in connection with = liên quan đến → mở thư nêu chủ đề, rất trang trọng.", e: "Sai: in connection to / in connect with → Đúng: in connection with + N. Không dùng cho thư bạn bè.", u: "Thư Task 1 trang trọng: I am writing in connection with your advertisement for part-time staff.", f: "connect (v), connection (n), with regard to (formal), regarding (prep)" },
  "further to": { m: "further to = tiếp theo (cuộc gọi, thư trước) → nhắc liên lạc trước đó.", e: "Rất trang trọng. Sai: Further to I called you / Further from → Đúng: Further to our phone conversation yesterday, ...", u: "Mở thư Task 1 trang trọng nối tiếp: Further to my letter of 3 April, I have still not received a reply.", f: "further (adj/adv), following (prep), with reference to (formal), as discussed (neutral)" },
  "the purpose of this letter is to": { m: "purpose (mục đích) → nói thẳng mục đích của thư.", e: "Sai: The purpose of this letter is for complain → Đúng: is to complain / to request. Quá cứng cho thư bạn bè.", u: "Thư trang trọng Task 1: The purpose of this letter is to request a refund for a faulty kettle.", f: "purpose (n), purposeful (adj), I am writing to (formal), on purpose (phr, cố ý)" },
  "i recently purchased": { m: "purchase (mua) trang trọng hơn buy → mở thư khiếu nại về hàng hóa.", e: "Sai: I recently purchase / have recently purchased + mốc thời gian quá khứ → Đúng: I recently purchased a laptop from your store.", u: "Thư khiếu nại Task 1: I recently purchased a washing machine from your Leeds branch.", f: "purchase (v/n), purchaser (n), buy (v, neutral), proof of purchase (n)" },
  "as you may be aware": { m: "be aware = có biết → mở ý nhắc thông tin người nhận có thể đã biết.", e: "Sai: As you may aware / As you may be know → Đúng: As you may be aware, ... Giọng trang trọng/bán trang trọng.", u: "Thư Task 1 gửi ban quản lý: As you may be aware, the lift has been out of order since Monday.", f: "aware (adj), awareness (n), As you know (neutral), As you may have heard (neutral)" },
  "i saw your advertisement in": { m: "advertisement (quảng cáo/tin tuyển dụng) → nêu nơi thấy tin đăng.", e: "Đọc Anh-Anh /ədˈvɜːtɪsmənt/. Sai: I saw your advertise in → Đúng: advertisement/advert. Giới từ: in a newspaper, on a website.", u: "Thư xin việc/hỏi thông tin: I saw your advertisement in the Evening Standard on 2 May.", f: "advertise (v), advertisement/advert (n), job advert (n), I am writing to apply for (formal)" },
  // Khiếu nại
  "i would like to draw your attention to": { m: "draw attention to = kéo sự chú ý về → chỉ ra vấn đề một cách lịch sự.", e: "Sai: draw your attention on / to draw your attention that → Đúng: draw your attention to + N. Không dùng thư bạn bè.", u: "Thư khiếu nại Task 1: I would like to draw your attention to the poor condition of the playground.", f: "attention (n), attentive (adj), I would like to point out that (formal), bring to sb's attention (phr)" },
  "i would like to point out that": { m: "point out = chỉ ra → nêu một sự thật, vấn đề.", e: "Sai: point out about / point that out that → Đúng: point out that + mệnh đề. Giọng trang trọng.", u: "Thư khiếu nại/đề xuất Task 1: I would like to point out that the bus was 40 minutes late.", f: "point out (phr v), point (n), highlight (v), I would like to draw your attention to (formal)" },
  "i was extremely disappointed with": { m: "disappointed with/by + điều gì → thất vọng về dịch vụ, sản phẩm.", e: "Sai: I was extremely disappointing → Đúng: disappointed (cảm xúc người). Giới từ: with/by + sự vật, in + người.", u: "Thư khiếu nại Task 1: I was extremely disappointed with the quality of the food.", f: "disappoint (v), disappointed (adj), disappointing (adj), disappointment (n)" },
  "i wish to express my dissatisfaction with": { m: "dis- (không) + satisfaction (hài lòng) → bày tỏ sự không hài lòng, rất trang trọng.", e: "Sai: dissatisfaction about / my unsatisfaction → Đúng: dissatisfaction with. Đừng trộn với giọng thân mật như I'm really fed up.", u: "Thư khiếu nại Task 1: I wish to express my dissatisfaction with the repairs carried out on my flat.", f: "satisfy (v), dissatisfied (adj), dissatisfaction (n), I am writing to complain about (formal)" },
  "to make matters worse": { m: "matters = mọi chuyện → làm mọi chuyện tệ hơn: thêm một vấn đề nữa.", e: "Sai: To make matter worse / To make the matters worst → Đúng: To make matters worse, ...", u: "Thư khiếu nại, đoạn thân: To make matters worse, the replacement was also faulty.", f: "worse (adj, so sánh hơn), worsen (v), What is more (formal), On top of that (informal)" },
  "this is not the first time": { m: "Nhấn mạnh vấn đề lặp lại → tăng sức nặng cho khiếu nại.", e: "Theo sau là thì hiện tại hoàn thành: This is not the first time this has happened. Sai: ...this happened.", u: "Thư khiếu nại Task 1: This is not the first time I have had problems with your delivery service.", f: "first (adj), again (adv), repeatedly (adv), Despite repeated requests (formal)" },
  "this has caused me considerable inconvenience": { m: "considerable (đáng kể) + inconvenience (sự bất tiện) → nêu hậu quả, trang trọng.", e: "Sai: caused me a considerable inconvenient → Đúng: considerable inconvenience (danh từ, không mạo từ). Giọng trang trọng.", u: "Thư khiếu nại, nêu hậu quả: This has caused me considerable inconvenience, as I had to take a day off work.", f: "inconvenience (n/v), inconvenient (adj), considerable (adj), considerably (adv)" },
  "i find this situation unacceptable": { m: "find + O + adj → thấy điều gì thế nào; unacceptable = không thể chấp nhận.", e: "Sai: I find this situation is unacceptable / not acceptable situation → Đúng: I find this situation unacceptable.", u: "Thư khiếu nại Task 1, kết đoạn thân: Frankly, I find this situation unacceptable.", f: "accept (v), acceptable (adj), unacceptable (adj), acceptance (n)" },
  "despite repeated requests": { m: "despite + N; repeated requests = yêu cầu nhiều lần → nhấn mạnh đã nhắc nhiều lần.", e: "Sai: Despite of repeated requests / Despite I requested → Đúng: Despite repeated requests, the heating has not been fixed.", u: "Thư khiếu nại chủ nhà Task 1: Despite repeated requests, nobody has come to repair the window.", f: "repeat (v), repeated (adj), repeatedly (adv), in spite of (prep)" },
  "i am still waiting for": { m: "still + hiện tại tiếp diễn → đến giờ vẫn đang chờ.", e: "Sai: I am still waiting my refund → Đúng: waiting for my refund. Nêu mốc: since 3 May.", u: "Thư khiếu nại Task 1: I am still waiting for the refund you promised three weeks ago.", f: "wait (v), waiting list (n), await (v, trang trọng), still (adv)" },
  "fell short of my expectations": { m: "fall short of = thiếu một đoạn mới tới → không đạt kỳ vọng.", e: "Sai: fell short to / fall short with → Đúng: fell short of my expectations (quá khứ fell, không phải felt).", u: "Thư khiếu nại Task 1: Unfortunately, the hotel fell far short of my expectations.", f: "fall short of (phr), expect (v), expectation (n), live up to (phr v, trái nghĩa)" },
  "i expect a full refund": { m: "full (toàn bộ) + refund (tiền hoàn) → đòi hoàn đủ tiền, giọng dứt khoát.", e: "Sai: I expect a full refunding / refund full → Đúng: I expect a full refund. Mạnh, chỉ dùng thư khiếu nại.", u: "Kết thư khiếu nại Task 1: Given these problems, I expect a full refund.", f: "refund (n/v), refundable (adj), I would like a replacement (formal), compensation (n)" },
  "i trust that you will": { m: "trust that = tin chắc rằng → yêu cầu lịch sự nhưng có sức ép.", e: "Sai: I trust you will to / I trust on you will → Đúng: I trust that you will deal with this matter promptly.", u: "Kết thư khiếu nại trang trọng: I trust that you will look into this matter without delay.", f: "trust (v/n), trustworthy (adj), I hope that (neutral), I look forward to (formal)" },
  "i will have no choice but to": { m: "no choice but to + V → không còn lựa chọn nào ngoài việc → cảnh báo.", e: "Sai: no choice but + V-ing / no choice than → Đúng: no choice but to take legal action. Dùng tiết chế, giữ lịch sự.", u: "Thư khiếu nại lần hai: If the problem is not solved, I will have no choice but to contact the council.", f: "choice (n), choose (v), be forced to (phr), otherwise (adv)" },
  "i hope this matter can be resolved quickly": { m: "resolve = giải quyết dứt điểm; bị động can be resolved → câu kết thư khiếu nại mềm mỏng.", e: "Sai: can be resolve / resolved quick → Đúng: can be resolved quickly. Giọng trang trọng, không dùng thư bạn bè.", u: "Câu kết thư khiếu nại Task 1: I hope this matter can be resolved quickly.", f: "resolve (v), resolution (n), solve (v), settle (v)" },
  // Yêu cầu lịch sự
  "i would be grateful if you could": { m: "grateful (biết ơn) + câu điều kiện → nhờ vả rất lịch sự.", e: "Sai: I would be grateful if you can / grateful that you could → Đúng: if you could + V. Hợp thư trang trọng.", u: "Yêu cầu trong thư Task 1 trang trọng: I would be grateful if you could send me a brochure.", f: "grateful (adj), gratitude (n), I would appreciate it if you could (formal), Could you (neutral)" },
  "i would appreciate it if you could": { m: "appreciate it if → trân trọng nếu ông/bà có thể → yêu cầu lịch sự.", e: "Đừng bỏ 'it': Sai: I would appreciate if you could → Đúng: I would appreciate it if you could...", u: "Thư trang trọng Task 1: I would appreciate it if you could reply by Friday.", f: "appreciate (v), appreciation (n), appreciative (adj), I would be grateful if (formal)" },
  "i would like to request": { m: "request (yêu cầu, đề nghị) trang trọng hơn ask for.", e: "Sai: request for a refund (động từ không cần for) → Đúng: request a refund; make a request for (danh từ).", u: "Thư trang trọng Task 1: I would like to request a change to my working hours.", f: "request (v/n), on request (phr), as requested (phr), ask for (phr v, neutral)" },
  "would it be possible to": { m: "Hỏi khả năng thay vì đòi hỏi → yêu cầu mềm, lịch sự.", e: "Sai: Would it be possible for change / to changing → Đúng: Would it be possible to change my booking? (động từ nguyên mẫu).", u: "Thư trang trọng/bán trang trọng: Would it be possible to reschedule the interview?", f: "possible (adj), possibility (n), possibly (adv), Could you possibly (neutral)" },
  "i was wondering if you could": { m: "Quá khứ tiếp diễn làm lời nhờ nhẹ nhàng hơn → nhờ vả khéo.", e: "Sai: I was wondering if you can / wonder you could → Đúng: I was wondering if you could + V. Hợp thư bán trang trọng và thân mật.", u: "Thư nhờ bạn/hàng xóm: I was wondering if you could water my plants while I'm away.", f: "wonder (v), Could you do me a favour? (informal), Would it be possible to (formal)" },
  "could you possibly": { m: "possibly làm câu nhờ mềm và lịch sự hơn Could you.", e: "Sai: Could you possible → Đúng: Could you possibly + V? Dùng được trong thư trung tính và thân mật.", u: "Thư bán trang trọng: Could you possibly send me the documents by Monday?", f: "possible (adj), possibly (adv), Would it be possible to (formal), Could you please (neutral)" },
  "could you do me a favour?": { m: "do sb a favour = giúp ai một việc → nhờ vả bạn bè.", e: "Anh-Anh: favour; Anh-Mỹ: favor. Sai: make me a favour → Đúng: do me a favour. Không dùng thư trang trọng.", u: "Thư thân mật Task 1: Could you do me a favour? I need someone to feed my cat next week.", f: "favour (n), favourite (adj), ask sb a favour (phr), I owe you one (informal)" },
  "i would like further information about": { m: "further information = thêm thông tin → hỏi chi tiết trang trọng.", e: "information không đếm được. Sai: further informations / an information → Đúng: further information about the course.", u: "Thư hỏi thông tin Task 1: I would like further information about the cost and timetable.", f: "inform (v), information (n), informative (adj), I am writing to enquire about (formal)" },
  "please let me know": { m: "let me know = cho tôi biết → yêu cầu phản hồi, dùng được nhiều giọng.", e: "Sai: Please let me to know / let me known → Đúng: Please let me know if... Trung tính, dùng cả thư bạn bè.", u: "Thư thân mật/bán trang trọng: Please let me know if you need anything else.", f: "let sb know (phr), inform (v, formal), Keep me posted (informal), Could you please confirm (neutral)" },
  "could you please confirm": { m: "confirm = xác nhận → nhờ xác nhận thông tin, lịch hẹn.", e: "Sai: confirm me the date / confirm about → Đúng: Could you please confirm the date? / confirm that...", u: "Thư trang trọng/bán trang trọng: Could you please confirm my booking for 12 June?", f: "confirm (v), confirmation (n), confirmed (adj), as requested (formal)" },
  "as requested": { m: "as requested = như đã được yêu cầu → gửi kèm thứ người nhận đã hỏi.", e: "Sai: as your request / as requesting → Đúng: as requested hoặc at your request. Giọng trang trọng.", u: "Thư trang trọng Task 1: As requested, I enclose a copy of my receipt.", f: "request (v/n), as agreed (phr), as discussed (phr), at your request (phr)" },
  "i enclose": { m: "en- (vào trong) + close → đặt vào trong phong bì, gửi kèm.", e: "Sai: I enclosed with this letter / I enclose here with → Đúng: I enclose a copy of... / Please find enclosed... (trang trọng).", u: "Thư trang trọng Task 1: I enclose a copy of my CV and two references.", f: "enclose (v), enclosure (n), enclosed (adj), attach (v, email)" },
  // Xin lỗi
  "please accept my apologies for": { m: "accept my apologies = nhận lời xin lỗi → xin lỗi trang trọng.", e: "Sai: accept my apology to / apologies about → Đúng: apologies for + N/V-ing. Với bạn bè: I'm really sorry.", u: "Thư xin lỗi trang trọng Task 1: Please accept my apologies for missing the meeting.", f: "apologise (v), apology (n), apologetic (adj), I sincerely apologise for (formal)" },
  "i sincerely apologise for": { m: "sincerely (chân thành) + apologise → xin lỗi trang trọng, thành khẩn.", e: "apologise for + N/V-ing; apologise to + người. Sai: apologise about / apologise you. Anh-Mỹ: apologize.", u: "Thư trang trọng Task 1: I sincerely apologise for the inconvenience caused.", f: "apologise (v), apology (n), sincere (adj), sincerely (adv)" },
  "i regret to inform you that": { m: "regret to + V = lấy làm tiếc phải → báo tin không vui, trang trọng.", e: "regret to inform (tiếc phải báo) khác regret informing (hối hận đã báo). Không dùng với bạn bè.", u: "Thư trang trọng báo tin: I regret to inform you that I must cancel my membership.", f: "regret (v/n), regrettable (adj), unfortunately (adv), I am afraid that (neutral)" },
  "i will be unable to attend": { m: "unable to = không thể → từ chối tham dự, trang trọng hơn can't come.", e: "Sai: unable attending / unable to attend to the meeting → Đúng: unable to attend the meeting (attend không cần to).", u: "Thư trang trọng Task 1: I am afraid I will be unable to attend the training session on Monday.", f: "able (adj), unable (adj), inability (n), I'll have to give it a miss (informal)" },
  "due to circumstances beyond my control": { m: "beyond my control = ngoài tầm kiểm soát của tôi → lý do khách quan.", e: "Sai: due to circumstances out my control / beyond of → Đúng: beyond my control. Trang trọng, hơi mơ hồ; nên nói thêm lý do cụ thể.", u: "Thư xin lỗi trang trọng: Due to circumstances beyond my control, I missed my appointment.", f: "circumstance (n), control (n/v), due to (prep), unforeseen (adj)" },
  "i am terribly sorry": { m: "terribly (vô cùng) nhấn mạnh sorry → xin lỗi chân thành.", e: "Bán trang trọng/thân mật. Sai: I am terrible sorry → Đúng: terribly sorry. Thư rất trang trọng nên dùng I sincerely apologise.", u: "Thư xin lỗi bạn/hàng xóm: I am terribly sorry about the noise last Saturday.", f: "sorry (adj), terribly (adv), I feel awful about (informal), apologise (v, formal)" },
  "i feel awful about": { m: "feel awful = thấy rất tệ, áy náy → xin lỗi thân mật.", e: "Thân mật. Sai: I feel awful for to miss / I feel awfully about → Đúng: I feel awful about missing your party.", u: "Thư xin lỗi bạn bè Task 1: I feel awful about forgetting your birthday.", f: "awful (adj), awfully (adv), I am terribly sorry (semi-formal), It completely slipped my mind (informal)" },
  "it completely slipped my mind": { m: "slip (tuột) + my mind → chuyện tuột khỏi đầu, quên mất.", e: "Thân mật. Sai: It completely slipped out my mind / I slipped my mind → Đúng: It completely slipped my mind.", u: "Thư xin lỗi bạn Task 1: I'm so sorry about Saturday – it completely slipped my mind.", f: "slip (v), forget (v), forgetful (adj), I feel awful about (informal)" },
  "i hope you can forgive me": { m: "forgive = tha thứ → kết lời xin lỗi thân mật, chân thành.", e: "Sai: forgive for me / forgive me to → Đúng: forgive me (for + V-ing). Không dùng với công ty.", u: "Thư xin lỗi bạn bè Task 1: I hope you can forgive me, and let me buy you dinner.", f: "forgive (v), forgiveness (n), forgiving (adj), Let me make it up to you (informal)" },
  "let me make it up to you": { m: "make it up to sb = bù đắp cho ai → đề nghị chuộc lỗi.", e: "Sai: let me make up it to you / make it up for you → Đúng: let me make it up to you. Thân mật.", u: "Thư xin lỗi bạn Task 1: Let me make it up to you – dinner is on me next week.", f: "make up for (phr v), make it up to sb (phr), compensate (v, formal), I hope you can forgive me (informal)" },
  // Cảm ơn
  "i am writing to thank you for": { m: "Nêu mục đích thư cảm ơn ngay câu đầu.", e: "Sai: thank you about / thank you for to help → Đúng: thank you for + N/V-ing. Hợp thư trang trọng và bán trang trọng.", u: "Câu mở thư cảm ơn Task 1: I am writing to thank you for your help during my stay.", f: "thank (v), thanks (n), thankful (adj), I am most grateful for (formal)" },
  "i am most grateful for": { m: "most ở đây = very (rất) → vô cùng biết ơn, giọng trang trọng.", e: "Sai: I am most grateful about / grateful to your help → Đúng: grateful for + việc, grateful to + người.", u: "Thư cảm ơn trang trọng: I am most grateful for your advice on my application.", f: "grateful (adj), gratitude (n), ungrateful (adj), appreciate (v)" },
  "thank you so much for": { m: "so much nhấn mạnh → cảm ơn nồng nhiệt, giọng thân mật/bán trang trọng.", e: "Sai: Thank you so much about / Thanks you so much → Đúng: Thank you so much for + N/V-ing.", u: "Thư cảm ơn bạn Task 1: Thank you so much for letting me stay at your flat.", f: "thank (v), Thanks a lot (informal), I can't thank you enough (informal), I am most grateful for (formal)" },
  "i can't thank you enough": { m: "Cảm ơn bao nhiêu cũng không đủ → biết ơn sâu sắc, thân mật.", e: "Thân mật (có viết tắt can't). Sai: I can't thank you enough for to help → Đúng: ...for helping me.", u: "Thư cảm ơn bạn Task 1: I can't thank you enough for looking after my dog.", f: "thank (v), Thank you so much (informal), I owe you one (informal), I am most grateful (formal)" },
  "it was so kind of you to": { m: "kind of sb to + V → ai đó thật tốt khi làm gì.", e: "Sai: It was so kind for you / kind of you for helping → Đúng: It was so kind of you to help me.", u: "Thư cảm ơn bán trang trọng/thân mật: It was so kind of you to invite me to your wedding.", f: "kind (adj), kindness (n), kindly (adv), How kind of you (phr)" },
  "your help was invaluable": { m: "in- ở đây không phải 'không': invaluable = quý đến mức không định giá được.", e: "Sai: hiểu invaluable = vô giá trị (đó là worthless/valueless). Đúng: invaluable = cực kỳ quý giá.", u: "Thư cảm ơn Task 1: Your help with the move was invaluable.", f: "value (n/v), valuable (adj), invaluable (adj), worthless (adj, trái nghĩa)" },
  "i owe you one": { m: "owe (nợ) + one (một lần giúp) → mình nợ cậu một lần.", e: "Rất thân mật, chỉ dùng thư bạn bè. Sai: I owe you a one / I owe to you one. Không dùng với công ty.", u: "Thư cảm ơn bạn Task 1: Thanks for covering my shift – I owe you one!", f: "owe (v), owing to (prep), Could you do me a favour? (informal), I can't thank you enough (informal)" },
  // Mời, nhận lời, từ chối
  "i would like to invite you to": { m: "invite sb to + sự kiện / to + V → lời mời lịch sự.", e: "Sai: invite you join / invite you for to come → Đúng: invite you to my party / to join us.", u: "Thư mời Task 1 (bán trang trọng): I would like to invite you to our office opening on 10 May.", f: "invite (v), invitation (n), inviting (adj), Would you like to come (informal)" },
  "we would be delighted if you could attend": { m: "delighted (rất vui) + if you could → lời mời trang trọng.", e: "Sai: delighted if you can attend to / delighting → Đúng: We would be delighted if you could attend. Quá trang trọng cho bạn thân.", u: "Thư mời trang trọng Task 1: We would be delighted if you could attend our annual dinner.", f: "delight (n/v), delighted (adj), delightful (adj), I would like to invite you to (formal)" },
  "would you like to come": { m: "Would you like to + V → lời mời thân mật, nhẹ nhàng.", e: "Sai: Would you like coming / Do you like to come (hỏi sở thích) → Đúng: Would you like to come to my party?", u: "Thư thân mật Task 1: Would you like to come and stay with us in August?", f: "Fancy coming? (very informal), Let me know if you can make it (informal), invite (v)" },
  "let me know if you can make it": { m: "make it = đến được, kịp tham dự → nhờ báo có đến được không.", e: "Thân mật. Sai: let me know if you can make / make it to come → Đúng: Let me know if you can make it.", u: "Kết thư mời bạn Task 1: The party starts at 8 – let me know if you can make it!", f: "make it (phr), Please reply by (formal), RSVP (abbr), Count me in (informal)" },
  "it would be lovely to see you": { m: "lovely (dễ thương, tuyệt) → mong gặp, giọng thân mật/ấm áp.", e: "Sai: It would be lovely seeing you / It will be lovely see you → Đúng: It would be lovely to see you.", u: "Thư mời/hồi âm thân mật: It would be lovely to see you before you leave for Canada.", f: "lovely (adj), Can't wait to see you (informal), I look forward to seeing you (neutral)" },
  "i would be delighted to accept": { m: "delighted to + V → nhận lời mời trang trọng, vui vẻ.", e: "Sai: delighted accepting / delighted to accepting → Đúng: I would be delighted to accept your invitation.", u: "Thư nhận lời trang trọng: Thank you for your kind invitation, which I would be delighted to accept.", f: "accept (v), acceptance (n), decline (v, từ chối), Count me in (informal)" },
  "count me in": { m: "Hãy tính cả tôi vào → đồng ý tham gia, rất thân mật.", e: "Rất thân mật. Sai: count in me / count me on → Đúng: Count me in! Trái nghĩa: Count me out.", u: "Thư trả lời bạn Task 1: A camping trip? Count me in!", f: "count (v), count me out (informal), I would be delighted to accept (formal)" },
  "i'll have to give it a miss": { m: "give sth a miss = bỏ qua, không tham gia → từ chối nhẹ nhàng thân mật.", e: "Thân mật (Anh-Anh). Sai: give a miss it / miss it a give → Đúng: I'll have to give it a miss this time.", u: "Thư từ chối lời mời bạn bè Task 1: Sadly, I'll have to give it a miss – I'm working that weekend.", f: "miss (v), I will be unable to attend (formal), Count me in (informal, trái nghĩa)" },
  "please reply by": { m: "reply by + ngày → hạn trả lời.", e: "by = trước/không muộn hơn; until = kéo dài đến. Sai: Please reply until Friday → Đúng: Please reply by Friday.", u: "Thư mời trang trọng/bán trang trọng: Please reply by 20 May so we can book the venue.", f: "reply (v/n), respond (v), RSVP (abbr), Let me know if you can make it (informal)" },
  // Khuyên
  "if i were you, i would": { m: "Câu điều kiện loại 2: giả sử tôi là bạn → lời khuyên.", e: "Dùng were, không dùng was trong văn viết. Sai: If I am you, I will → Đúng: If I were you, I would...", u: "Thư khuyên bạn Task 1: If I were you, I would talk to your manager first.", f: "advise (v), advice (n), You might want to (informal), I would suggest that (formal)" },
  "you might want to": { m: "might want to + V → gợi ý nhẹ nhàng, không ép.", e: "Sai: You might want go / you might want to going → Đúng: You might want to book early.", u: "Thư thân mật hoặc bán trang trọng: You might want to bring a jacket – it gets cold at night.", f: "If I were you (informal), I would recommend (neutral), suggest (v)" },
  "i would suggest that": { m: "suggest that + S + (should) V nguyên mẫu → đề xuất, trang trọng.", e: "Sai: I suggest you to do → Đúng: I suggest that you (should) do / I suggest doing.", u: "Thư đề xuất Task 1 gửi ban quản lý: I would suggest that more bins be provided.", f: "suggest (v), suggestion (n), I would recommend (neutral), One option would be to (neutral)" },
  "i would recommend": { m: "recommend + N/V-ing → giới thiệu, khuyên dùng.", e: "Sai: recommend you to visit (ít chuẩn) / recommend to go → Đúng: I would recommend visiting / recommend that you visit.", u: "Thư cho bạn/khách Task 1: I would recommend the Italian restaurant near the station.", f: "recommend (v), recommendation (n), I would suggest that (formal), You might want to (informal)" },
  "one option would be to": { m: "option (lựa chọn) → đưa ra một phương án, giọng khách quan.", e: "Sai: One option would be to booking / is booking → Đúng: One option would be to + V nguyên mẫu.", u: "Thư đề xuất/khuyên Task 1: One option would be to move the meeting to Friday.", f: "option (n), optional (adj), alternative (n), Alternatively (adv)" },
  // Kết thư trang trọng
  "i look forward to your reply": { m: "look forward to + N/V-ing → mong chờ thư trả lời.", e: "to là giới từ. Sai: look forward to hear from you → Đúng: look forward to hearing / to your reply. Hợp thư trang trọng.", u: "Câu kết thư trang trọng Task 1: I look forward to your reply.", f: "look forward to (phr v), I hope to hear from you soon (neutral), Write back soon (informal)" },
  "thank you in advance for your help": { m: "in advance = trước → cảm ơn trước cho sự giúp đỡ sắp tới.", e: "Sai: Thanks in advanced / in advance of your help → Đúng: Thank you in advance for your help. Đôi khi bị coi là hơi ép.", u: "Câu kết thư yêu cầu bán trang trọng: Thank you in advance for your help.", f: "advance (n), in advance (phr), advanced (adj, nâng cao), I look forward to your reply (formal)" },
  "should you require any further information": { m: "Should you + V = If you should → câu điều kiện đảo ngữ rất trang trọng.", e: "Sai: Should you requires / If should you require → Đúng: Should you require any further information, please contact me.", u: "Câu kết thư trang trọng/thư xin việc: Should you require any further information, please do not hesitate to contact me.", f: "require (v), requirement (n), If you need more details (neutral), I can be contacted on (formal)" },
  "i can be contacted on": { m: "contact bị động + on + số điện thoại (Anh-Anh) → cách liên hệ.", e: "Anh-Anh: on + số điện thoại, at + email. Sai: contacted by 0123... / contact to me.", u: "Thư xin việc/trang trọng: I can be contacted on 07700 900123 or at an.nguyen@email.com.", f: "contact (v/n), contactable (adj), contact details (n), Should you require (formal)" },
  "thank you for your time and consideration": { m: "consideration = sự cân nhắc → cảm ơn đã dành thời gian xem xét (đơn).", e: "Sai: Thanks for your time and considering → Đúng: Thank you for your time and consideration. Trang trọng, hợp thư xin việc.", u: "Câu kết thư xin việc Task 1: Thank you for your time and consideration.", f: "consider (v), consideration (n), considerate (adj), I am available for interview (formal)" },
  "i am available for interview": { m: "available (sẵn sàng, rảnh) + for interview → sẵn sàng đi phỏng vấn.", e: "Sai: I am available to interview (dễ hiểu là mình phỏng vấn người khác) → Đúng: available for interview / for an interview.", u: "Thư xin việc Task 1: I am available for interview at any time next week.", f: "available (adj), availability (n), interview (n/v), interviewer/interviewee (n)" },
  // Kết thư thân mật
  "i hope to hear from you soon": { m: "hear from = nhận tin từ → mong sớm nhận hồi âm.", e: "Trung tính, dùng được với bạn bè và người quen. Sai: hope to hear you soon → Đúng: hear from you soon.", u: "Câu kết thư thân mật/bán trang trọng: I hope to hear from you soon.", f: "hear from (phr v), Write back soon (informal), I look forward to your reply (formal)" },
  "write back soon": { m: "write back = viết thư trả lời → giục bạn hồi âm.", e: "Rất thân mật, dạng mệnh lệnh. Sai: dùng trong thư gửi công ty. Không viết Write me back soon trong văn Anh-Anh chuẩn.", u: "Câu kết thư bạn bè Task 1: Write back soon and tell me all your news!", f: "write back (phr v), reply (v), I hope to hear from you soon (neutral), Keep me posted (informal)" },
  "can't wait to see you": { m: "can't wait = nóng lòng → háo hức được gặp.", e: "Thân mật, có thể lược chủ ngữ I. Sai: Can't wait seeing you / Can't wait for see you → Đúng: Can't wait to see you!", u: "Câu kết thư bạn bè Task 1: Can't wait to see you next month!", f: "wait (v), I look forward to seeing you (neutral), It would be lovely to see you (informal)" },
  "give my love to": { m: "give my love to sb = gửi lời thương đến ai → nhắn hỏi thăm người nhà.", e: "Rất thân mật. Sai: Give my love for your family / Send love to your family's → Đúng: Give my love to your family.", u: "Câu cuối thư bạn bè/người nhà: Give my love to your parents.", f: "love (n/v), Say hello to (informal), Send my regards to (semi-formal), Lots of love (informal)" },
  "say hello to": { m: "say hello to sb = gửi lời chào ai → nhắn chào người quen chung.", e: "Thân mật. Sai: Say hello for / Say hi with → Đúng: Say hello to Tom for me.", u: "Câu cuối thư thân mật: Say hello to everyone at the office for me.", f: "say hi to (informal), Give my love to (informal), Send my regards to (semi-formal)" },
  "anyway, i'd better go": { m: "Anyway (dù sao thì) + I'd better go → chuyển ý để kết thư thân mật.", e: "I'd better = I had better + V nguyên mẫu. Sai: I'd better to go / I'd better going. Chỉ dùng thư bạn bè.", u: "Câu chuyển sang kết thư bạn bè Task 1: Anyway, I'd better go – I have to cook dinner.", f: "had better (modal), Anyway (adv), That's all for now (informal), Write back soon (informal)" },
  "keep me posted": { m: "post = cập nhật tin tức → keep me posted: nhớ báo tin cho mình.", e: "Thân mật. Sai: Keep me post / keep posted me → Đúng: Keep me posted. Thư trang trọng dùng Please keep me informed.", u: "Câu kết thư bạn bè Task 1: Good luck with the interview, and keep me posted!", f: "keep sb informed (formal), keep sb updated (neutral), Please let me know (neutral)" }
}); })(typeof self !== 'undefined' ? self : this);
